INSERT INTO public.strategies (id, name, description, params, builtin, created_at) VALUES ('83095c88-4836-4219-a6e7-6240fe134d49', 'Balanced rotation (default)', 'The original ASTR mix: trend 25, momentum 25, volume 20, relative strength 15, volatility quality 15. Buys the best-scoring name shortly after the open and sells before the close. Good all-round starting point.', '{"weight_trend": 25, "weight_volume": 20, "num_day_trades": 2, "weight_momentum": 25, "min_score_to_trade": 60, "weight_relative_strength": 15, "weight_volatility_quality": 15}', true, '2026-08-08 00:07:03.736451+00');
INSERT INTO public.strategies (id, name, description, params, builtin, created_at) VALUES ('fc99a1e4-686c-4a18-b961-22b7f3426059', 'Trend follower', 'Leans hard on trend (40) and relative strength (20), lighter on short-term momentum. Fewer, steadier picks; tends to hold market leaders instead of chasing one-day spikes.', '{"weight_trend": 40, "weight_volume": 15, "num_day_trades": 2, "weight_momentum": 15, "min_score_to_trade": 62, "weight_relative_strength": 20, "weight_volatility_quality": 10}', true, '2026-08-08 00:07:03.736451+00');
INSERT INTO public.strategies (id, name, description, params, builtin, created_at) VALUES ('d72c5d37-a356-4881-9e26-4163a6638321', 'Momentum burst', 'Momentum 40 and volume 25 dominate. Picks the fastest movers with heavy participation — more day-trade signals, bigger swings both ways.', '{"weight_trend": 15, "weight_volume": 25, "num_day_trades": 2, "weight_momentum": 40, "min_score_to_trade": 58, "weight_relative_strength": 10, "weight_volatility_quality": 10}', true, '2026-08-08 00:07:03.736451+00');
INSERT INTO public.strategies (id, name, description, params, builtin, created_at) VALUES ('bf5f3062-546c-4b2c-a9fe-6cb189ec778c', 'Careful / low volatility', 'Volatility quality 30 with a higher score bar (68). Skips wild names, trades less often, aimed at smoother equity curves on a small account.', '{"weight_trend": 25, "weight_volume": 15, "num_day_trades": 1, "weight_momentum": 20, "min_score_to_trade": 68, "weight_relative_strength": 10, "weight_volatility_quality": 30}', true, '2026-08-08 00:07:03.736451+00');
